import java.util.Scanner;

public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    String S = sc.next();
    sc.close();

    int[] count = new int[256];

    for (int i = 0; i < S.length(); i++) {
        count[S.charAt(i)]++;
    }

    for (int i = 0; i < S.length(); i++) {
        if (count[S.charAt(i)] == 1) {
            System.out.println(i + 1);
            return;
        }
    }
}
